import { Outlet, useMatch } from 'react-router-dom';
import { SplitView } from '@/components/layout/SplitView.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { t } from '@/i18n/index.js';
import { atLeast, useWindowClass } from '@/lib/windowClass.js';
import { Notebook } from './Notebook.js';
import styles from './NotebookLayout.module.css';

/**
 * The notebook and a word, side by side on an expanded window
 * (lib/windowClass.ts): the list stays where it was and the word opens
 * beside it, so going through a page of words is a click each rather than
 * open, read, back, find your place, open the next.
 *
 * Both addresses keep their meaning. /notebook is the list, with a quiet
 * note where the word will appear; /words/:id is the list with that word
 * open and marked. On anything narrower each is its own screen, exactly as
 * on a phone.
 */
export function NotebookLayout(): React.JSX.Element {
  const size = useWindowClass();
  const wordId = useMatch('/words/:wordId')?.params.wordId;

  if (!atLeast(size, 'expanded')) return <Outlet />;

  return (
    <SplitView
      list={<Notebook />}
      listLabel={t('notebook.title')}
      detailKey={wordId ?? ''}
      detail={
        wordId === undefined ? (
          <div className={styles.pick}>
            <EmptyState
              icon="notebook"
              tone="quiet"
              middle
              title={t('notebook.pickTitle')}
              body={t('notebook.pickBody')}
            />
          </div>
        ) : (
          <Outlet />
        )
      }
    />
  );
}
